<?php
require __DIR__.'/includes/bootstrap.php';require_admin();require __DIR__.'/includes/layout.php';$id=(int)($_GET['edit']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'save';if($action==='toggle'&&$id){$pdo->prepare('UPDATE dental_services SET is_active=1-is_active WHERE id=?')->execute([$id]);audit($pdo,'service.availability_toggled','service',$id);flash('success','Service availability updated.');redirect('services.php');}if($action==='delete'&&$id){$q=$pdo->prepare('SELECT COUNT(*) FROM appointments WHERE service_id=?');$q->execute([$id]);if($q->fetchColumn())flash('error','This service has appointment history and cannot be removed. Deactivate it instead.');else{$pdo->prepare('DELETE FROM dental_services WHERE id=?')->execute([$id]);flash('success','Unused service removed.');}redirect('services.php');}$name=post_string('name',120);$desc=post_string('description',3000);$price=filter_var($_POST['price']??null,FILTER_VALIDATE_FLOAT);$duration=filter_var($_POST['duration_minutes']??null,FILTER_VALIDATE_INT);$errors=[];if($name===''||$price===false||$price<0||$duration===false||$duration<5)$errors[]='Enter a name, non-negative price and a valid duration.';if(!$errors){try{if($id){$q=$pdo->prepare('UPDATE dental_services SET name=?,description=?,price=?,duration_minutes=? WHERE id=?');$q->execute([$name,$desc?:null,$price,$duration,$id]);}else{$q=$pdo->prepare('INSERT INTO dental_services(name,description,price,duration_minutes) VALUES(?,?,?,?)');$q->execute([$name,$desc?:null,$price,$duration]);$id=(int)$pdo->lastInsertId();}audit($pdo,'service.saved','service',$id);flash('success','Dental service saved.');redirect('services.php');}catch(PDOException $e){$errors[]='A service with that name already exists.';}}}
$edit=$id?$pdo->prepare('SELECT * FROM dental_services WHERE id=?'):null;if($edit){$edit->execute([$id]);$edit=$edit->fetch();}$services=$pdo->query('SELECT s.*,(SELECT COUNT(*) FROM appointments a WHERE a.service_id=s.id) bookings FROM dental_services s ORDER BY s.name')->fetchAll();page_header('Dental Services','services');
?><?php if(!empty($errors)):?><div class="alert error"><?=e(implode(' ',$errors))?></div><?php endif?><div class="grid panels"><section class="card"><h2>Services and pricing</h2><div class="table-wrap"><table><thead><tr><th>Service</th><th>Price</th><th>Duration</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($services as $s):?><tr><td><strong><?=e($s['name'])?></strong><br><small><?=e($s['description'])?></small></td><td>₱<?=number_format((float)$s['price'],2)?></td><td><?=$s['duration_minutes']?> min</td><td><span class="badge <?=$s['is_active']?'approved':'cancelled'?>"><?=$s['is_active']?'Active':'Inactive'?></span></td><td class="actions"><a class="btn secondary sm" href="?edit=<?=$s['id']?>">Edit</a><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$s['id']?>"><input type="hidden" name="action" value="toggle"><button class="btn secondary sm"><?=$s['is_active']?'Disable':'Enable'?></button></form><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$s['id']?>"><input type="hidden" name="action" value="delete"><button class="btn danger sm" data-confirm="Remove this unused service?">Remove</button></form></td></tr><?php endforeach?><?php if(!$services):?><tr><td colspan="5" class="empty">No services configured.</td></tr><?php endif?></tbody></table></div></section><section class="card"><h2><?=$edit?'Edit service':'Add service'?></h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=e((string)($edit['id']??''))?>"><label class="full">Service name<input name="name" required value="<?=e($edit['name']??'')?>"></label><label>Price (PHP)<input type="number" min="0" step="0.01" name="price" required value="<?=e((string)($edit['price']??''))?>"></label><label>Duration (minutes)<input type="number" min="5" step="5" name="duration_minutes" required value="<?=e((string)($edit['duration_minutes']??60))?>"></label><label class="full">Description<textarea name="description" rows="4"><?=e($edit['description']??'')?></textarea></label><div class="full"><button>Save service</button></div></form></section></div><?php page_footer();
